import{_ as e,o as a,c as i,ag as o}from"./chunks/framework.wGDfT7ie.js";const p=JSON.parse('{"title":"Innovation and differentiation","description":"","frontmatter":{},"headers":[],"relativePath":"innovation.md","filePath":"innovation.md"}'),n={name:"innovation.md"};function r(s,t,l,d,c,f){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="innovation-and-differentiation" tabindex="-1">Innovation and differentiation <a class="header-anchor" href="#innovation-and-differentiation" aria-label="Permalink to &quot;Innovation and differentiation&quot;">​</a></h1><h2 id="what-s-novel" tabindex="-1">What&#39;s novel <a class="header-anchor" href="#what-s-novel" aria-label="Permalink to &quot;What&#39;s novel&quot;">​</a></h2><ul><li><strong>Privacy-preserving autonomous agent</strong> — Combines AI-driven allocation (deterministic risk engine) with privacy primitives: proof-gating, confidential transactions, and selective disclosure. The agent acts on your behalf; intents stay hidden; actions are verifiable.</li><li><strong>Proof-gated session keys (Starknet AA)</strong> — Uses Starknet&#39;s native account abstraction (session keys) plus proof verification. The agent needs <em>both</em> a valid session <em>and</em> a valid proof to execute. That combination is rare: delegation with cryptographic guarantees.</li><li><strong>STARKs for execution, Groth16 for privacy</strong> — Execution proofs are verified via Integrity (STARK/SHARP); confidential transfers use a Groth16 verifier (Garaga on Sepolia). One stack for both verifiable execution and confidential balances.</li><li><strong>Selective disclosure + confidential on one stack</strong> — You can prove compliance or eligibility (selective disclosure) while also holding confidential positions (private deposits). Same app, same chain, same narrative.</li><li><strong>Complete confidential transfer cycle</strong> — Private deposits <em>and</em> private withdrawals. Nullifier-based double-spend prevention. Your amounts stay hidden from deposit to withdrawal.</li><li><strong>Multi-dimensional selective disclosure</strong> — Beyond basic thresholds: risk compliance (VaR, Sharpe), performance proofs (APY over time), KYC eligibility, and portfolio aggregation across protocols.</li><li><strong>Cross-protocol privacy aggregation</strong> — Prove total portfolio value across Ekubo, JediSwap, and private commitments without revealing individual protocol amounts or allocation strategy.</li></ul><h2 id="privacy-features" tabindex="-1">Privacy features <a class="header-anchor" href="#privacy-features" aria-label="Permalink to &quot;Privacy features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td>Private Deposits</td><td>Hide deposit amounts using commitments</td></tr><tr><td>Private Withdrawals</td><td>Withdraw without revealing amounts (nullifier-based)</td></tr><tr><td>Risk Compliance</td><td>Prove portfolio risk below threshold</td></tr><tr><td>Performance Proofs</td><td>Prove APY exceeded target over period</td></tr><tr><td>KYC Eligibility</td><td>Prove financial standing for compliance</td></tr><tr><td>Portfolio Aggregation</td><td>Prove total value without breakdown</td></tr></tbody></table><h2 id="starknet-native" tabindex="-1">Starknet-native <a class="header-anchor" href="#starknet-native" aria-label="Permalink to &quot;Starknet-native&quot;">​</a></h2><ul><li>Built for <strong>Starknet</strong> (Sepolia for demo; mainnet-ready). Uses native account abstraction, Integrity fact registry, and existing DeFi protocols (Ekubo, JediSwap).</li><li>No mock data: real prover on Sepolia, real Integrity, real ERC20 token. Proof-gated deposits and disclosures are fully on-chain and verifiable.</li><li><strong>Garaga integration</strong> for on-chain Groth16 verification of privacy proofs.</li></ul><p>Next: <a href="/docs/faq.html">FAQ</a></p>',8)])])}const h=e(n,[["render",r]]);export{p as __pageData,h as default};
